from collections import defaultdict

def count_distinct_prime_factors(n):
    count = 0
    if n % 2 == 0:
        count += 1
        while n % 2 == 0:
            n //= 2
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            count += 1
            while n % i == 0:
                n //= i
    if n > 2:
        count += 1
    return count

def max_revenue(N, S):
    dp = defaultdict(int)
    dp[0] = 0

    for mask in range(1, 1 << N):
        total_sum = 0
        for j in range(N):
            if mask & (1 << j):
                total_sum += S[j]

        dp[mask] = max(dp[mask], dp[mask ^ (1 << j)] + count_distinct_prime_factors(total_sum))

    return dp[(1 << N) - 1]

